  "(Claude Code·Codex에 설치된 것 — 실행 때 그대로 쓰임)": "(installed in Claude Code and Codex — used as-is on every run)",
  "개인 Google 로그인은 Gemini CLI에서 지원이 끝나서, Gemini CLI는 API 키로만 써.": "Gemini CLI no longer supports personal Google sign-in, so it runs with an API key only.",
  "Claude·ChatGPT(Codex)·Gemini·Hermes·로컬 모델을 한 사무실에 모아 팀으로 일 시켜봐.": "Bring Claude, ChatGPT (Codex), Gemini, Hermes and local models into one office and put them to work as a team.",
  "개인 계정 로그인은 지원 종료 → 설정에서 Gemini API 키를 입력해줘": "Personal account sign-in is no longer supported → enter a Gemini API key in Settings",
  "여러 AI CLI(Claude Code·Codex·Gemini CLI·Hermes)와 OpenAI 호환 API를 한 화면에서 팀으로 묶어 쓰는 로컬 앱이야. 서버는 이 PC(127.0.0.1)에서만 열리고, 런타임 의존성이 없어 가벼워.": "A local app that teams up several AI CLIs (Claude Code, Codex, Gemini CLI, Hermes) and OpenAI-compatible APIs in one screen. The server only listens on this PC (127.0.0.1) and has no runtime dependencies, so it stays light.",
  // ── 세션 불러오기 (import.js·main.js·server) ──
  "다른 AI에서 세션 불러오기": "Import a session from another AI",
  "Claude Code·Codex CLI에서 하던 대화를 골라 여기서 이어서 할 수 있어. 불러올 때 원래 기록은 읽기만 해. Claude는 갈래(포크)로 이어가서 원래 기록이 그대로 남고, Codex는 같은 대화에 이어 붙어(Codex에서도 계속 볼 수 있어).": "Pick a conversation you had in Claude Code or Codex CLI and continue it here. Importing only reads the original history. Claude continues on a fork, so the original stays untouched; Codex appends to the same conversation (you can keep seeing it in Codex too).",
  "전체": "All",
  "제목·폴더·내용으로 검색": "Search by title, folder or content",
  "기록 찾는 중…": "Looking for history…",
  "찾는 중…": "Searching…",
