  "localOnly 는 true 나 false 여야 해.": "localOnly must be true or false.",
  "네가 맞다고 보면 에이전트 편집 창의 역할 노트에 직접 써 넣어.": "If you think it's right, write it into the role notes in the agent editor yourself.",
  "항목의 출처(source)가 필요해.": "The item needs a source.",
  "고른 글이 있던 메시지를 찾지 못했어.": "Couldn't find the message the selected text came from.",
  "채팅에서 고름": "Picked from the chat",
  // ── 역할 노트: 이어 가는 대화 (codex.js) ──
  "역할 노트가 바뀌었어. 앞에서 받은 역할 노트 대신 아래를 따라. 나머지 지시는 그대로야.": "Your role notes have changed. Follow the ones below instead of the role notes you got earlier. The rest of your instructions stay the same.",
  "역할 노트에서 이번 일과 관련된 항목을 더 줄게. 앞에서 받은 역할 노트와 함께 따라.": "Here are more role-note items related to this task. Follow them together with the role notes you got earlier.",
  "앞에서 받은 역할 노트는 이제 쓰지 마.": "Don't use the role notes you got earlier anymore.",
  // ── 역할 노트: 서버 견고함 (notes.js·orchestrator.js) ──
  "지금 상태({from})에서 {to}(으)로는 바꿀 수 없어.": "This item can't go from {from} to {to}.",
  "역할 노트를 저장하지 못했어 ({code}).": "Couldn't save the role notes ({code}).",
  "역할 노트 파일을 읽지 못해서 이번 실행은 역할 노트 없이 했어.": "Couldn't read the role notes file, so this run went without role notes.",
  // ── 역할 노트: 편집 창 (rolenotes.js·manage.js) ──
  "초안 {n} — {name}의 역할 노트 열기": "Drafts {n} — open {name}'s role notes",
  "{action}: {what}": "{action}: {what}",
  "고치던 글이 저장되지 않았어. 버릴까?": "The text you were editing isn't saved. Discard it?",
  "다시 꺼내기": "Restore",
  "확정으로 돌려서 다음 일에 다시 넣어.": "Puts it back as accepted, so it goes into the next tasks again.",
  "초안으로 돌려. 다시 받아야 다음 일에 들어가.": "Puts it back as a draft. It goes into the next tasks only after you accept it again.",
