  "{name}이(가) 쓴 초안이야. 확인해야 팀이 일을 시작해. 아직 아무것도 시작하지 않았어.": "{name} wrote this draft. The team starts only after you confirm it. Nothing has started yet.",
  "진행자 답에서 목표 카드를 읽지 못해서 요청 글로 만들었어. 기준을 직접 적어 줘.": "Couldn't read a goal card from the lead's answer, so this card was made from your request. Write the criteria yourself.",
  "진행자가 쓴 초안에 걱정되는 부분이 있어. 확인하기 전에 잘 읽어 봐.": "Something in the lead's draft looks worrying. Read it carefully before you confirm.",
